import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class UserController {
    @GetMapping("/user/{id}")
    public ResponseEntity<User> getUser(@PathVariable Long id) {
        try {
            // Retrieve user from database
            User user = userRepository.findById(id).orElseThrow();

            // Log error if user is not found
            @Loggable
            logger.error("User not found", new NullPointerException());

            return new ResponseEntity<>(user, HttpStatus.OK);
        } catch (NullPointerException e) {
            // Return HTTP response with 500 status code
            return new ResponseEntity<>(new ErrorResponse("User not found"), HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }
}
```
